#!/usr/bin/env python3
"""
erdos_predictor v1.0 -- agent-0195

Per-prime test of the OBJ1-C mechanism.  The class-mean argument in
  commons/findings/agent-0195_OBJ1-C-ANSWERED-MECHANISM-...md
says the representation count f(n) of 4/n = 1/x+1/y+1/z is driven by the divisor
abundance of the head denominators m_d = (n+d)/4 over the smallest admissible
d = -n (mod 4).  If that is the mechanism and not just a class-average
coincidence, then a score built ONLY from divisor counts of m_d for a handful of
small d -- no representation counting at all -- must predict f(n) prime by prime.

SCORE(n; D) = sum over d = -n (mod 4), 0 < d <= D  of  tau(m_d^2) / d
              with m_d = (n+d)/4     (d=1 term is exact, by Theorem H1)

Reports Pearson and Spearman correlation of log SCORE against log f(n), and the
class means of SCORE (which must reproduce 1 < 17 < 13 < 5 < 19 < 11 < 7 < 23).

Usage:  python3 agent-0195_erdos_predictor_v1.0.py [--D 25] [--limit 25000]
"""
import json, sys, math
from collections import defaultdict

DEC = "commons/data/agent-0195_erdos_decomposition_25000_20260806T0320Z.json"
CEN = "commons/data/agent-0185_erdos_census_50000_PARTIAL_20260805T1630Z.json"


def spf_sieve(m):
    s = list(range(m + 1))
    i = 2
    while i * i <= m:
        if s[i] == i:
            for j in range(i * i, m + 1, i):
                if s[j] == j:
                    s[j] = i
        i += 1
    return s


def tau_sq(m, spf):
    t = 1
    while m > 1:
        p = spf[m]; e = 0
        while m % p == 0:
            m //= p; e += 1
        t *= 2 * e + 1
    return t


def spearman(xs, ys):
    def rank(v):
        order = sorted(range(len(v)), key=lambda i: v[i])
        r = [0.0] * len(v)
        i = 0
        while i < len(order):
            j = i
            while j + 1 < len(order) and v[order[j + 1]] == v[order[i]]:
                j += 1
            avg = (i + j) / 2 + 1
            for k in range(i, j + 1):
                r[order[k]] = avg
            i = j + 1
        return r
    return pearson(rank(xs), rank(ys))


def pearson(xs, ys):
    n = len(xs)
    mx = sum(xs) / n; my = sum(ys) / n
    sx = math.sqrt(sum((x - mx) ** 2 for x in xs))
    sy = math.sqrt(sum((y - my) ** 2 for y in ys))
    return sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / (sx * sy)


def main():
    D = 25; limit = 25000
    if "--D" in sys.argv: D = int(sys.argv[sys.argv.index("--D") + 1])
    if "--limit" in sys.argv: limit = int(sys.argv[sys.argv.index("--limit") + 1])
    try:
        rows = [(r["n"], r["total"]) for r in json.load(open(DEC))["rows"] if r["n"] <= limit]

