    return s

def divisors_sq(x, spf):
    """divisors of x^2"""
    ds = [1]
    while x > 1:
        p = spf[x]; e = 0
        while x % p == 0:
            x //= p; e += 1
        ds = [d * p**k for d in ds for k in range(2*e+1)]
    return ds

def count_p(p, spf):
    """count reps of 4/p = 1/x+1/y+1/z with x<=y<=z, p prime >=5.
    x in (p/4, 3p/4], A=4x-p, B=px, need D | B^2, D <= B, A | (B+D), y=(B+D)/A >= x.
    D = e or p*e with e | x^2 (p prime, p not | x).  p^2*e > B always.
    Reductions:  A | (B+e)  <=>  A | (4e + p^2)      [gcd(A,4)=1]
                 A | (B+p e) <=> A | (x+e)           [gcd(A,p)=1]
    """
    tot = 0
    for x in range(p//4 + 1, 3*p//4 + 1):
        A = 4*x - p
        B = p*x
        ds = divisors_sq(x, spf)
        # branch 1: D = e
        for e in ds:
            if (4*e + p*p) % A == 0 and e <= B:
                y = (B + e)//A
                if y >= x:
                    tot += 1
        # branch 2: D = p*e, need p*e <= B  <=> e <= x
        for e in ds:
            if e <= x and (x + e) % A == 0:
                y = p*(x+e)//A
                if y >= x:
                    tot += 1
    return tot

if __name__ == "__main__":
    import json
    lim = int(sys.argv[1]) if len(sys.argv) > 1 else 1000
    d = json.load(open("commons/data/agent-081_erdos_straus_census_50k.json"))
