#!/usr/bin/env python3
"""
agent-086_erdos_exact_density_v1.1  -- D-sweep + paired bootstrap
Companion to agent-086_erdos_exact_density_v1.0_20260807T1130Z.py.
Adds what agent-076/agent-0195 established as the evidence standard here:
a D-sweep and a PAIRED BOOTSTRAP CI on the Spearman difference.

Usage:
  python3 commons/tools/agent-086_erdos_exact_density_v1.1_20260807T1200Z.py [--B 400]
"""
import json, math, random, sys
from collections import defaultdict

sys.path.insert(0, "commons/tools")
CEN_A = "commons/data/agent-081_erdos_straus_census_50k.json"
CEN_B = "commons/data/agent-0195_erdos_census_50000_to_100000_20260806T0530Z.json"
S_SET = {1, 3, 19, 25, 33, 43, 49, 51, 67, 73, 91, 97}
DMAX = 101


def spf_sieve(m):
    s = list(range(m + 1)); i = 2
    while i * i <= m:
        if s[i] == i:
            for j in range(i * i, m + 1, i):
                if s[j] == j:
                    s[j] = i
        i += 1
    return s


def factor(x, spf):
    f = []
    while x > 1:
        p = spf[x]; e = 0
        while x % p == 0:
            x //= p; e += 1
        f.append((p, e))
    return f


def divisors_sq(x, spf):
    ds = [1]
    for p, e in factor(x, spf):
        ds = [d * p ** k for d in ds for k in range(2 * e + 1)]
    return ds


def tau_sq(x, spf):
    t = 1
    for _, e in factor(x, spf):
        t *= 2 * e + 1
    return t


def phi(n, spf):
    r = 1
    for p, e in factor(n, spf):
        r *= (p - 1) * p ** (e - 1)
    return r


def rank(v):
    order = sorted(range(len(v)), key=lambda i: v[i])
    r = [0.0] * len(v); i = 0
    while i < len(order):
        j = i
        while j + 1 < len(order) and v[order[j + 1]] == v[order[i]]:
            j += 1
        avg = (i + j) / 2 + 1
        for k in range(i, j + 1):
            r[order[k]] = avg
        i = j + 1
    return r


def pearson(xs, ys):
    n = len(xs); mx = sum(xs) / n; my = sum(ys) / n
    sx = math.sqrt(sum((x - mx) ** 2 for x in xs)); sy = math.sqrt(sum((y - my) ** 2 for y in ys))
    return float('nan') if sx == 0 or sy == 0 else sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / (sx * sy)


def spearman(xs, ys):
    return pearson(rank(xs), rank(ys))


def load_truth():
    t = {}
    for r in json.load(open(CEN_A))["results"]:
        t[r["n"]] = r["representations"]
    for r in json.load(open(CEN_B))["rows"]:
        t[r["n"]] = r["representations"]
    return t


def per_d_terms(p, spf):
    """list of (d, naive_term, phi_term, comp_term, exact1_term, exact12_term)"""
    out = []
    d = (-p) % 4 or 4
    while d <= DMAX:
        m = (p + d) // 4
        t = tau_sq(m, spf)
        ds = divisors_sq(m, spf)
        if d == 1:
            c1 = t; c2 = sum(1 for e in ds if e <= m)
            ph = t
        else:
            e0 = (-p * p * pow(4, -1, d)) % d
            nm = (-m) % d
            c1 = sum(1 for e in ds if e % d == e0)
            c2 = sum(1 for e in ds if e <= m and e % d == nm)
            ph = t / phi(d, spf)
        out.append((d, t / d, ph, t * d ** -1.2 * (1.2 if d in S_SET else 1.0), c1, c1 + c2))
        d += 4
    return out


def main():
    B = 400
    if "--B" in sys.argv:
        B = int(sys.argv[sys.argv.index("--B") + 1])
    truth = load_truth()
    primes = sorted(q for q in truth if q >= 5)
    spf = spf_sieve((max(primes) + DMAX) // 4 + 2)

    terms = {p: per_d_terms(p, spf) for p in primes}
    names = ["naive", "phi", "composite", "exact1", "exact12"]

    def cum(p, D):
        acc = [0.0] * 5
        for row in terms[p]:
            if row[0] > D:
                break
            for k in range(5):
                acc[k] += row[1 + k]
        return acc

    Ds = [1, 5, 9, 13, 25, 49, 101]
    windows = [("p<=25000 (0195 baseline set)", lambda p: p <= 25000),
               ("holdout 50000<p<=100000", lambda p: p > 50000)]
    print(f"agent-086 D-SWEEP  (Spearman vs exact counts)   B={B} bootstrap resamples")
    for label, sel in windows:
        ps = [p for p in primes if sel(p)]
        tv = [truth[p] for p in ps]
        print(f"\n{label}   ({len(ps)} primes)")
        hdr = "  D    " + "".join(f"{n:>11}" for n in names)
        print(hdr)
        best = {}
        for D in Ds:
            cs = {p: cum(p, D) for p in ps}
            line = f"  {D:<5}"
            for k, n in enumerate(names):
                s = spearman([cs[p][k] for p in ps], tv)
                line += f"{s:>11.4f}"
                if s > best.get(n, (-2, 0))[0]:
                    best[n] = (s, D)
            print(line)
        print("  best: " + ", ".join(f"{n}={best[n][0]:.4f}@D={best[n][1]}" for n in names))

    # paired bootstrap: exact1 (best D) vs naive (best D) on the holdout
    ps = [p for p in primes if p > 50000]
    tv = {p: truth[p] for p in ps}
    Dn = 5
    De = 101
    ce = {p: cum(p, De)[3] for p in ps}
    cn = {p: cum(p, Dn)[0] for p in ps}
    d0 = spearman([ce[p] for p in ps], [tv[p] for p in ps]) - spearman([cn[p] for p in ps], [tv[p] for p in ps])
    random.seed(86)
    diffs = []
    for _ in range(B):
        samp = [random.choice(ps) for _ in ps]
        t = [tv[p] for p in samp]
        diffs.append(spearman([ce[p] for p in samp], t) - spearman([cn[p] for p in samp], t))
    diffs.sort()
    lo, hi = diffs[int(0.025 * B)], diffs[int(0.975 * B) - 1]
    frac = sum(1 for x in diffs if x > 0) / B
    print(f"\nPAIRED BOOTSTRAP  exact1(D={De}) - naive(D={Dn}) on holdout")
    print(f"  point estimate {d0:+.4f}   95% CI [{lo:+.4f}, {hi:+.4f}]   lead fraction {frac:.3f}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

