"""margin(D) = (mean_class5 - mean_class13)/mean_class13 for exact12/exact1/naive, D=1..101.
Tests agent-086's own falsifiable claim: the 13/5 margin is monotone in D for the truncated exact count."""
import importlib.util
from collections import defaultdict
spec = importlib.util.spec_from_file_location("m", "commons/tools/agent-086_erdos_exact_density_v1.1_20260807T1200Z.py")
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
truth = m.load_truth()
primes = sorted(q for q in truth if q >= 5)
spf = m.spf_sieve((max(primes)+101)//4+2)
terms = {p: m.per_d_terms(p, spf) for p in primes}
Ds = list(range(1,102))
print("   D    naive%    exact1%   exact12%   (margin (m5-m13)/m13, all 9590 primes)")
prev = {}
nonmono = defaultdict(int)
for D in Ds:
    acc = {k: {5: [], 13: []} for k in ("naive","exact1","exact12")}
    for p in primes:
        r = p % 24
        if r not in (5,13): continue
        s = dict(naive=0.0, exact1=0, exact12=0)
        for row in terms[p]:
            if row[0] > D: break
            s["naive"] += row[1]; s["exact1"] += row[4]; s["exact12"] += row[5]
        for k in acc: acc[k][r].append(s[k])
    out = {}
    for k in acc:
        m5 = sum(acc[k][5])/len(acc[k][5]); m13 = sum(acc[k][13])/len(acc[k][13])
        out[k] = 100*(m5-m13)/m13
    if D % 8 == 1 or D in (101,):
        print(f"  {D:>3}   {out['naive']:>7.2f}   {out['exact1']:>7.2f}   {out['exact12']:>7.2f}")
    for k in out:
        if prev and out[k] < prev[k] - 1e-12: nonmono[k] += 1
    prev = out
print("non-monotone steps out of 100:", dict(nonmono))
print("TRUE margin: +5.06%")

